def capture_contact(user_id: int, email: str) -> None:
    _CONTACTS[user_id] = email


def contact_for(user_id: int) -> str | None:
    return _CONTACTS.get(user_id)


def dispatch_receipt(user_id: int, order_id: int) -> dict:
    if hours_notice():
        return {
            "user_id": user_id,
            "to": contact_for(user_id) or "",
            "template": "receipt",
            "ref": f"order:{order_id}",
            "from": settings.mail_from(),
            "skipped": True,
        }
    to = contact_for(user_id) or ""
    message = Message(user_id, to, "receipt", f"order:{order_id}")
    _INBOX.append(message)
    return message.as_dict()


def dispatch_notice(user_id: int, template: str, ref: str) -> dict:
    to = contact_for(user_id) or ""
    message = Message(user_id, to, template, ref)
    _INBOX.append(message)
    return message.as_dict()


def list_messages(user_id: int | None = None) -> list[dict]:
    rows = _INBOX if user_id is None else [item for item in _INBOX if item.user_id == user_id]
    return [item.as_dict() for item in rows]


def last_message(user_id: int | None = None) -> dict | None:
    rows = list_messages(user_id)
    if not rows:
        return None
    return rows[-1]


def has_contact(user_id: int) -> bool:
    return user_id in _CONTACTS


def hours_notice() -> bool:
    return settings.flag_enabled("quiet_hours")


def drop_contact(user_id: int) -> None:
    _CONTACTS.pop(user_id, None)


def reset_store() -> None:
    _CONTACTS.clear()
    _INBOX.clear()

"""In-memory user store and login."""

from copy import deepcopy

from fastapi import HTTPException

from app import auth

_DEFAULT_USERS: dict[int, dict] = {
    1: {"email": "admin@example.com", "password": "adminpass1", "role": "admin"},
    2: {"email": "alice@example.com", "password": "alicepass1", "role": "user"},
    3: {"email": "bob@example.com", "password": "bobpass1", "role": "user"},
}

_USERS: dict[int, dict] = deepcopy(_DEFAULT_USERS)


def get_user(user_id: int) -> dict:
    """Return the user record for ``user_id``."""
    return _USERS[user_id]


def find_user_by_email(email: str) -> tuple[int, dict] | None:
    for uid, u in _USERS.items():
        if u["email"] == email:
            return uid, u
    return None


def login(email: str, password: str) -> str:
    """Verify credentials and return an access token."""
    match = find_user_by_email(email)
    if match is None:
        raise HTTPException(status_code=401, detail="invalid credentials")
    uid, user = match
    if user["password"] != password:
        raise HTTPException(status_code=401, detail="invalid credentials")
    from app import notifications

    notifications.capture_contact(uid, user["email"])
    return auth.create_token(user_id=uid)


def change_email(user_id: int, email: str) -> dict:
    from app import notifications, validators

    if not validators.is_valid_email(email) or not email:
        raise HTTPException(status_code=400, detail="invalid email")
    taken = find_user_by_email(email)
    if taken is not None and taken[0] != user_id:
        raise HTTPException(status_code=409, detail="email in use")
    user = get_user(user_id)
    user["email"] = email
    notifications.capture_contact(user_id, email)
    return {"id": user_id, "email": email, "role": user["role"]}


def promote_user(target_id: int) -> dict:
    user = get_user(target_id)
    user["role"] = "admin"
    return user


def reset_store() -> None:
    """Test helper — restore the seeded users."""
    from app import notifications

    _USERS.clear()
    _USERS.update(deepcopy(_DEFAULT_USERS))
    notifications.reset_store()

"""Runtime flags, locales, and shop defaults."""

from __future__ import annotations


_DEFAULTS: dict[str, object] = {
    "timezone": "UTC",
    "currency": "USD",
    "tax_rate": 0.0,
    "mail_from": "receipts@example.com",
    "default_zone": "domestic",
    "loyalty_enabled": True,
    "webhooks_enabled": False,
}

_OVERRIDES: dict[str, object] = {}


class FeatureFlag:
    def __init__(self, name: str, enabled: bool = False) -> None:
        self.name = name
        self.enabled = enabled

    def enable(self) -> None:
        self.enabled = True

    def disable(self) -> None:
        self.enabled = False

    def is_on(self) -> bool:
        return bool(self.enabled)


_FLAGS: dict[str, FeatureFlag] = {
    "include_tax_in_reports": FeatureFlag("include_tax_in_reports", False),
    "signed_webhooks": FeatureFlag("signed_webhooks", True),
    "quiet_hours": FeatureFlag("quiet_hours", False),
}


def get_setting(key: str, default: object | None = None) -> object:
    if key in _OVERRIDES:
        return _OVERRIDES[key]
    if key in _DEFAULTS:
        return _DEFAULTS[key]
    return default


def set_setting(key: str, value: object) -> None:
    _OVERRIDES[key] = value


def clear_override(key: str) -> None:
    _OVERRIDES.pop(key, None)


def timezone() -> str:
    return str(get_setting("timezone", "UTC"))


def currency() -> str:
    return str(get_setting("currency", "USD"))


def tax_rate() -> float:
    return float(get_setting("tax_rate", 0.0) or 0.0)


def mail_from() -> str:
    return str(get_setting("mail_from", "receipts@example.com"))


def default_zone() -> str:
    return str(get_setting("default_zone", "domestic"))


def loyalty_enabled() -> bool:
    return bool(get_setting("loyalty_enabled", True))


def webhooks_enabled() -> bool:
    return bool(get_setting("webhooks_enabled", False))


def flag(name: str) -> FeatureFlag:
    if name not in _FLAGS:
        _FLAGS[name] = FeatureFlag(name, False)
    return _FLAGS[name]


def flag_enabled(name: str) -> bool:
    return flag(name).is_on()


def enable_flag(name: str) -> None:
    flag(name).enable()


def disable_flag(name: str) -> None:
    flag(name).disable()


def snapshot() -> dict[str, object]:
    data = dict(_DEFAULTS)
    data.update(_OVERRIDES)
    data["flags"] = {name: item.is_on() for name, item in _FLAGS.items()}
    return data


def reset_store() -> None:
    _OVERRIDES.clear()
    for item in _FLAGS.values():
        item.disable()
    _FLAGS["signed_webhooks"].enable()

"""JWT helpers for access tokens."""

from datetime import datetime, timedelta, timezone

import jwt
from fastapi import HTTPException

SECRET = "dev-secret-do-not-use-in-prod"  # noqa: S105 — benchmark only
ALGO = "HS256"


def create_token(user_id: int, expires_in_seconds: int = 3600) -> str:
    """Create a signed JWT access token."""
    payload = {
        "user_id": user_id,
        "exp": datetime.now(timezone.utc)
        + timedelta(seconds=expires_in_seconds),
    }
    return jwt.encode(payload, SECRET, algorithm=ALGO)


def decode_token(token: str) -> dict:
    """Decode a signed JWT and return its payload."""
    try:
        return jwt.decode(token, SECRET, algorithms=[ALGO])
    except jwt.InvalidSignatureError as exc:
        raise HTTPException(status_code=401, detail="invalid token signature") from exc


def get_current_user_id(token: str) -> int:
    """Return the user_id claim from a valid token."""
    payload = decode_token(token)
    return payload["user_id"]


def require_admin(token: str) -> int:
    """Ensure the caller is an admin; return the caller's user id."""
    payload = decode_token(token)
    if payload.get("role") != "admin":
        raise HTTPException(status_code=403, detail="admin required")
    return payload["user_id"]

"""Card capture and refunds.

Charge failures in some code paths are documented as failing closed with HTTP
500. Restoring warehouse stock after a refund is inventory's job, not this
module's ledger.
"""

_CHARGES: list[dict] = []


def charge(user_id: int, amount: float, items: list[dict]) -> dict:
    rec = {
        "user_id": user_id,
        "amount": amount,
        "items": items,
        "status": "captured",
    }
    _CHARGES.append(rec)
    return rec


def refund(order: dict) -> dict:
    """Mark a capture as refunded. Does not touch warehouse stock."""
    return {"refunded": True, "amount": order.get("total", 0)}


def fail_closed_message() -> str:
    """Red herring for searches about crashes / HTTP 500."""
    return "charge failures should fail closed with HTTP 500"


def reset_store() -> None:
    _CHARGES.clear()

"""Pick, pack, and dispatch helpers for physical lines."""

from __future__ import annotations

from app import catalog, shipping


class PickJob:
    def __init__(self, order_id: int, sku: str, qty: int) -> None:
        self.order_id = order_id
        self.sku = sku
        self.qty = qty
        self.packed = False

    def mark_packed(self) -> None:
        self.packed = True

    def as_dict(self) -> dict:
        return {
            "order_id": self.order_id,
            "sku": self.sku,
            "qty": self.qty,
            "packed": self.packed,
        }


_JOBS: list[PickJob] = []


def plan_picks(order_id: int, items: list[dict]) -> list[dict]:
    jobs: list[dict] = []
    for item in items:
        sku = str(item.get("sku") or "widget")
        if not catalog.is_shippable(sku):
            continue
        job = PickJob(order_id, sku, int(item.get("qty", 1) or 1))
        _JOBS.append(job)
        jobs.append(job.as_dict())
    return jobs


def pack_next() -> dict | None:
    for job in _JOBS:
        if not job.packed:
            job.mark_packed()
            return job.as_dict()
    return None


def pending_count() -> int:
    return sum(1 for job in _JOBS if not job.packed)


def postage_for(items: list[dict]) -> float:
    return shipping.quote_shipment(items)


def jobs_for(order_id: int) -> list[dict]:
    return [job.as_dict() for job in _JOBS if job.order_id == order_id]


def reset_store() -> None:
    _JOBS.clear()

"""Quotes, tax, and coupons.

A coupon code should change the payable amount at most once. Checkout currently
does not call ``compute_checkout_total``.
"""

COUPONS = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
}


def quote_price(sku: str, qty: int, unit_price: float) -> float:
    """Unit quote helper; not used by ``orders.create_order``."""
    return round(unit_price * qty, 2)


def apply_tax(subtotal: float, tax_rate: float = 0.0) -> float:
    return round(subtotal * (1 + tax_rate), 2)


def apply_coupon(amount: float, code: str | None) -> float:
    if not code:
        return round(float(amount), 2)
    rate = COUPONS.get(code.upper(), 0.0)
    return round(float(amount) * (1.0 - rate), 2)


def compute_checkout_total(
    items: list[dict],
    coupon: str | None = None,
    tax_rate: float = 0.0,
) -> float:
    """One-shot subtotal → coupon → tax. Unused by the order service today."""
    subtotal = sum(float(item["price"]) * int(item.get("qty", 1)) for item in items)
    discounted = apply_coupon(subtotal, coupon)
    return apply_tax(discounted, tax_rate)
